using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// Set up options with the default reflection-based resolver
var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
// In .NET 9+ there's a generic overload on the options object via the
// IJsonTypeInfoResolver, but the simplest strongly-typed path is:
JsonTypeInfo<Person> typedInfo = JsonSerializer.Deserialize<JsonTypeInfo<Person>>(
    "null", options) is not null ? null! : null!; // placeholder — see below

// Actually, the clean generic API lives on the resolver itself:
JsonTypeInfo<Person> resolved =
    (JsonTypeInfo<Person>)options.TypeInfoResolver!.GetTypeInfo(typeof(Person), options)!;

Console.WriteLine($"Resolved typed metadata for: {resolved.Type.Name}");
Console.WriteLine($"  Kind = {resolved.Kind}");

// 2) Probe without throwing: TryGetTypeInfo (added in .NET 9)
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? found))
{
    Console.WriteLine($"TryGetTypeInfo(Person) succeeded — Kind = {found!.Kind}");
}
else
{
    Console.WriteLine("TryGetTypeInfo(Person) returned false");
}

// Probe for a type the resolver knows nothing about (no resolver at all scenario)
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (empty.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? notFound))
{
    Console.WriteLine($"Unexpected: found metadata via empty resolver");
}
else
{
    Console.WriteLine("TryGetTypeInfo(Person) on empty resolver returned false — no exception thrown");
}

