{
    Console.WriteLine($"\nTryGetTypeInfo(Person) succeeded — Kind = {found!.Kind}");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo(Person) returned false");
}

// Probe for a type whose resolver intentionally yields nothing
var empty = new JsonSerializerOptions
{
    TypeInfoResolver = new EmptyResolver()
};

if (empty.TryGetTypeInfo(typeof(Person), out _))
{
    Console.WriteLine("Unexpected: found metadata via empty resolver");
}
else
{
    Console.WriteLine("TryGetTypeInfo(Person) on empty resolver → false (no exception thrown)");
}

